import RNA, random, sys
from multiprocessing import Pool

target='(((((.((((((.((((((.((((((.((((((.((((((....((((((......)))))).)))))).(((((...(((((((...)))))))))))).)))))).((((((((((((...)))))))...))))).))))))....))))))....))))))....)))))'
n=len(target)
stack=[];pairs={}
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop();pairs[j]=i;pairs[i]=j

def random_init(rng):
    seq=['A']*n
    for i in range(n):
        if i in pairs and i<pairs[i]:
            r=rng.choice(['GC','CG','AU','UA','GU','UG'])
            seq[i]=r[0]; seq[pairs[i]]=r[1]
    return ''.join(seq)

def mutate(seq, rng):
    s=list(seq)
    i=rng.randint(0,n-1)
    if i in pairs:
        j=pairs[i]
        r=rng.choice(['GC','CG','AU','UA','GU','UG'])
        s[i]=r[0]; s[j]=r[1]
    else:
        s[i]=rng.choice('ACGU')
    return ''.join(s)

def score(seq):
    fc=RNA.fold_compound(seq)
    mfe,e=fc.mfe()
    d=RNA.bp_distance(mfe,target)
    return d, mfe

def worker(seed):
    rng=random.Random(seed)
    seq=random_init(rng)
    d,mfe=score(seq)
    best_d=d; best=seq
    T=3.0
    for step in range(3000):
        seq2=mutate(seq,rng)
        d2,mfe2=score(seq2)
        if d2<d or (d2==d and rng.random()<0.3) or rng.random()<pow(2.718,-(d2-d)/max(T,0.01)):
            seq=seq2; d=d2
        if d<best_d:
            best_d=d; best=seq
        if d==0:
            break
        T*=0.998
    return best_d, best

if __name__=='__main__':
    seeds=list(range(2000))
    with Pool(32) as p:
        results=p.map(worker, seeds)
    results.sort(key=lambda x:x[0])
    print(results[0][0])
    print(results[0][1])
    # print top 5
    for d,s in results[:5]:
        print(d, s, file=sys.stderr)
